import math

def count_divisors(n):
    """Calculates the number of positive divisors of n."""
    if n == 1:
        return 1
    count = 1
    temp_n = n
    i = 2
    while i * i <= temp_n:
        if temp_n % i == 0:
            exponent = 0
            while temp_n % i == 0:
                exponent += 1
                temp_n //= i
            count *= (exponent + 1)
        i += 1
    if temp_n > 1:
        count *= 2
    return count

def calculate_N(x):
    """Calculates N(x) = (tau(x^2) - 1) / 2."""
    if x == 1:
        return 0
    x_squared = x * x
    tau_x_squared = count_divisors(x_squared)
    # N(x) = (tau(x^2) - 1) / 2
    return (tau_x_squared - 1) // 2

