def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_N(x):
    if x <= 0:
        return None
    factors = prime_factorization(x)

    # x = p1^a1 * p2^a2 * ...
    # x^2 = p1^(2a1) * p2^(2a2) * ...
    # tau(x^2) = (2a1 + 1) * (2a2 + 1) * ...

    tau_x_squared = 1
    for exponent in factors.values():
        tau_x_squared *= (2 * exponent + 1)

    # N(x) = (tau(x^2) - 1) / 2
    # Since tau(x^2) is always odd (product of odd numbers 2a_i + 1), 
    # tau(x^2) - 1 is always even, so N(x) is an integer.
    N_x = (tau_x_squared - 1) // 2

    return N_x, tau_x_squared

